def test_probe():
    harness = ExecutionHarness()
    test_code = '''
import unittest
class TestExample(unittest.TestCase):
    def test_pass(self):
        self.assertTrue(True)
'''
    bundle = {'test_example.py': test_code}
    import builtins
    original_import = builtins.__import__
    def mock_import(name, *args, **kwargs):
        if name == 'pytest':
            raise ImportError('Mocked for probe')
        return original_import(name, *args, **kwargs)
    builtins.__import__ = mock_import
    try:
        report = harness.verify_bundle(bundle)
        tests_gate = report.gate('tests')
        if tests_gate:
            print(f'Status: {tests_gate.status}')
            print(f'Detail: {tests_gate.detail}')
            # If TypeError occurs, detail might contain 'TypeError' or 'missing 1 required positional argument'
            if 'TypeError' in tests_gate.detail or 'missing 1 required' in tests_gate.detail:
                print('HYPOTHESIS_SUPPORTED')
            else:
                print('HYPOTHESIS_NOT_SUPPORTED')
        else:
            print('NO_TESTS_GATE')
    finally:
        builtins.__import__ = original_import

test_probe()

